 16	function escapeHtml(str) {
 17	  if (str === null || str === undefined) return '';
 18	  return String(str)
 19	    .replace(/&/g, '&amp;')
 20	    .replace(/</g, '&lt;')
 21	    .replace(/>/g, '&gt;')
 22	    .replace(/"/g, '&quot;');
 23	}
 24	
 25	function formatDate(isoString) {
 26	  if (!isoString) return '—';
 27	  try {
 28	    var d = new Date(isoString);
 29	    if (isNaN(d.getTime())) return escapeHtml(isoString);
 30	    var pad = function (n) { return String(n).padStart(2, '0'); };
 31	    var timeStr = pad(d.getHours()) + ':' + pad(d.getMinutes());
 32	
 33	    var now = new Date();
 34	    // Strip times for day-boundary comparisons
 35	    var today    = new Date(now.getFullYear(),    now.getMonth(),    now.getDate());
 36	    var itemDay  = new Date(d.getFullYear(),      d.getMonth(),      d.getDate());
 37	    var diffDays = Math.round((today - itemDay) / 86400000);
 38	
 39	    if (diffDays === 0) return 'Today, ' + timeStr;
 40	    if (diffDays === 1) return 'Yesterday, ' + timeStr;
 41	    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
 42	    if (diffDays < 7)  return ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][d.getDay()] + ', ' + d.getDate() + ' ' + months[d.getMonth()] + ', ' + timeStr;
 43	
 44	    // Older: show short date like "12 Feb 2026, 16:41"
 45	    return d.getDate() + ' ' + months[d.getMonth()] + ' ' + d.getFullYear() + ', ' + timeStr;
 46	  } catch (_) {
 47	    return escapeHtml(isoString);
 48	  }
 49	}
 50	
 51	function statusBadge(status) {
 52	  if (!status) return '';
 53	  var cls = 'badge badge-' + status.toLowerCase().replace(/_/g, '-');
 54	  return '<span class="' + cls + '">' + escapeHtml(status) + '</span>';
 55	}
