 57	// Cache of namespaced key → display name, populated by views that fetch project data.
 58	// breadcrumb().project() reads from here automatically.
 59	// The cache key is the composite `repo + '/' + slug` to prevent collisions
 60	// between same-slug projects in different repositories.
 61	// Bounded to MAX_SIZE entries; oldest entries are evicted when the cap is exceeded.
 62	var ProjectNameCache = (function () {
 63	  var MAX_SIZE = 200;
 64	  var _cache = {};
 65	  var _keys = []; // insertion-order tracker for eviction (no duplicates)
 66	
 67	  return {
 68	    /**
 69	     * Store a display name for a project.
 70	     * @param {string} key  - Namespaced key in the form `repo/slug`.
 71	     *   Legacy callers that have not yet been migrated to the namespaced form (e.g.
 72	     *   `project-detail.js` — see WP-013) may pass a bare slug. Those entries will
 73	     *   not be found by namespaced `get()` calls until the caller is migrated.
 74	     * @param {string} name - Display name to cache.
 75	     */
 76	    set: function (key, name) {
 77	      if (!key || !name || !name.trim()) return;
 78	      var trimmed = name.trim();
 79	      // Update the value; only add to order tracker if this is a new key.
 80	      // NOTE: This is FIFO eviction, not LRU. Updating an existing key refreshes
 81	      // its value but does NOT move it to the back of the eviction queue — the key
 82	      // retains its original insertion position. For this cache (display names for
 83	      // up to 200 projects, rarely refreshed), FIFO is correct and sufficient.
 84	      if (!Object.prototype.hasOwnProperty.call(_cache, key)) {
 85	        _keys.push(key);
 86	        // Evict oldest entry if cap exceeded.
 87	        if (_keys.length > MAX_SIZE) {
 88	          var oldest = _keys.shift();
 89	          delete _cache[oldest];
 90	        }
 91	      }
 92	      _cache[key] = trimmed;
 93	    },
 94	    /**
 95	     * Retrieve the display name for a project.
 96	     * @param {string} key - Namespaced key in the form `repo/slug`.
 97	     *   Falsy values (null, undefined, empty string) are handled gracefully: a null/undefined
 98	     *   key returns null without throwing; an empty string key falls through to the slug
 99	     *   extraction path and returns an empty string.
100	     * @returns {string|null} Cached display name, or the slug portion of the key (after the
101	     *   last '/') if not found — so breadcrumbs show a readable label before project data is
102	     *   fetched. Returns null for null/undefined input.
103	     */
104	    get: function (key) {
105	      if (_cache[key]) return _cache[key];
106	      // Fall back to the slug portion (after the last '/') so breadcrumbs show
107	      // a readable label even before the project data is fetched.
108	      var lastSlash = key ? key.lastIndexOf('/') : -1;
109	      return lastSlash >= 0 ? key.slice(lastSlash + 1) : key;
110	    },
111	    /**
112	     * Returns the current number of cached entries.
113	     * Intended for testing; not part of the public API.
114	     */
115	    _size: function () {
116	      return _keys.length;
117	    },
118	  };
119	}());
